impl Solution{pub fn multiply(a:String,b:String)->String{if a=="0"||b=="0"{return"0".into()}let(a,b)=(a.as_bytes(),b.as_bytes());let mut d=vec![0i32;a.len()+b.len()];for i in (0..a.len()).rev(){for j in (0..b.len()).rev(){let p=(a[i]-b'0')as i32*(b[j]-b'0')as i32+d[i+j+1];d[i+j+1]=p%10;d[i+j]+=p/10;}}let st=if d[0]==0{1}else{0};d[st..].iter().map(|&x|(b'0'+x as u8)as char).collect()}}
